from pysat.solvers import Glucose4
import itertools

# 3 orbits of size 8: A, B, C
# Vertices 0..7, 8..15, 16..23
# Edges are defined by shifts.
# For each pair of orbits (including same orbit), we can choose some shifts.
# To get ~33 edges, we need about 33/8 = 4.125 shifts.
# Let's just use a SAT solver on the shifts!

# Variables:
# For each pair of orbits (X, Y) in {A, B, C}x{A, B, C} with X <= Y
# If X == Y, shifts can be 1, 2, 3, 4. (Shift 4 gives 4 edges, others give 8)
# If X < Y, shifts can be 0, 1, 2, 3, 4, 5, 6, 7. (Each gives 8 edges)

shifts = []
# X == Y
for X in range(3):
    for s in range(1, 5):
        shifts.append((X, X, s))
# X < Y
for X in range(3):
    for Y in range(X+1, 3):
        for s in range(8):
            shifts.append((X, Y, s))

print("Total shifts:", len(shifts))

def get_edges(active_shifts):
    edges = []
    for X, Y, s in active_shifts:
        if X == Y:
            for i in range(8):
                u = X * 8 + i
                v = X * 8 + (i + s) % 8
                if u < v:
                    edges.append((u, v))
                elif u > v:
                    edges.append((v, u))
        else:
            for i in range(8):
                u = X * 8 + i
                v = Y * 8 + (i + s) % 8
                edges.append((min(u, v), max(u, v)))
    return list(set(edges))

def has_cycle_up_to(edges, max_len):
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # BFS to find short cycles
    for start in range(24):
        # queue stores (node, parent, depth)
        q = [(start, -1, 0)]
        visited = {start: 0}
        while q:
            curr, parent, depth = q.pop(0)
            if depth == max_len // 2 + 1:
                continue
            for nxt in adj[curr]:
                if nxt == parent:
                    continue
                if nxt in visited:
                    cycle_len = depth + visited[nxt] + 1
                    if cycle_len <= max_len:
                        return True
                else:
                    visited[nxt] = depth + 1
                    q.append((nxt, curr, depth + 1))
    return False

# We need at least 33 edges.
# Let's just brute force combinations of shifts.
# We need about 4 or 5 shifts.
# 4 shifts of size 8 = 32 edges (not enough)
# 5 shifts of size 8 = 40 edges
# 4 shifts of size 8 + 1 shift of size 4 = 36 edges.
# Let's try all subsets of shifts of size 4 and 5.

valid_graphs = []
for k in [4, 5]:
    for active in itertools.combinations(shifts, k):
        edges = get_edges(active)
        if len(edges) >= 33:
            if not has_cycle_up_to(edges, 6):
                print("Found!", len(edges))
                print(edges)
                valid_graphs.append(edges)
                break
    if valid_graphs:
        break
if not valid_graphs:
